function cupboardCheck(bool $ok,string $why):void{if(!$ok)throw new RuntimeException($why);}
function cupboardRequest(array $get=[],array $post=[]):string{
 global $root,$config;
 $code='putenv('.var_export('ANKH_ADMIN_CONFIG='.$config,true).');$_GET='.var_export($get,true).';$_POST='.var_export($post+['csrf'=>'cupboard-fixture'],true).';$_SERVER["REQUEST_METHOD"]='.var_export($post?'POST':'GET',true).';$_SERVER["REMOTE_ADDR"]="127.0.0.1";$_SERVER["HTTP_HOST"]="localhost";$_SERVER["SCRIPT_NAME"]="/index.php";require '.var_export($root.'/index.php',true).';';
 exec(escapeshellarg(PHP_BINARY).' -d display_errors=1 -r '.escapeshellarg($code).' 2>&1',$output,$exit);$html=implode("\n",$output);cupboardCheck($exit===0&&!preg_match('/(?:Fatal error|Warning|Notice):/',$html),'Request error: '.substr($html,-1200));return $html;
}
try{
 $db=new PDO('sqlite:'.$temp.'/fixture.sqlite',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$source=file_get_contents($root.'/index.php');preg_match('/CREATE TABLE IF NOT EXISTS business_supplies \(.*?\n\);/s',$source,$schema);$db->exec($schema[0]);
 $db->exec("INSERT INTO business_supplies(item,category,quantity,supplier,ordered_date,status,item_cost,shipping,request_key,created,updated) VALUES('Legacy envelopes','Envelopes & packaging',2,'Legacy shop','2025-01-01','Received',500,100,'legacy','2025-01-01','2025-01-01')");
 cupboardRequest(['view'=>'supplies']);cupboardCheck((int)$db->query('SELECT received_quantity FROM business_supplies WHERE id=1')->fetchColumn()===2,'Existing received purchases migrate safely');
 $before=$db->query('SELECT * FROM products ORDER BY id')->fetchAll(PDO::FETCH_ASSOC);
 $input=['action'=>'supply_item_save','return'=>'supplies','return_section'=>'cupboard','request_key'=>str_repeat('c',32),'name'=>'Labels <fixture>','category'=>'Labels','specification'=>'100 × 150mm waterproof','supplier'=>'Preferred shop','product_url'=>'https://example.com/labels','backup_supplier'=>'Backup shop','backup_url'=>'https://example.com/backup','usual_quantity'=>3,'usual_cost'=>'12.34','stock_level'=>'Out','stock_note'=>'No rolls left','requested_by'=>'Tony','notes'=>'Buy the waterproof version'];
 cupboardRequest(['view'=>'supplies'],$input);$id=(int)$db->query('SELECT id FROM business_supply_items')->fetchColumn();$item=static function()use($db,$id):array{return $db->query('SELECT * FROM business_supply_items WHERE id='.$id)->fetch(PDO::FETCH_ASSOC);};
 cupboardRequest(['view'=>'supplies'],$input);cupboardCheck((int)$db->query('SELECT COUNT(*) FROM business_supply_items')->fetchColumn()===1,'Repeated item submission is idempotent');
 cupboardCheck((int)$item()['usual_cost']===1234&&(int)$db->query('SELECT COUNT(*) FROM business_supplies')->fetchColumn()===1,'Saving a supply does not create spending');
 $change=static function(string $operation,array $extra=[],?int $revision=null)use($id,$item):string{return cupboardRequest(['view'=>'supplies','section'=>'shopping'],['action'=>'supply_item_change','return'=>'supplies','return_section'=>'shopping','cupboard_id'=>$id,'cupboard_revision'=>$revision??$item()['revision'],'operation'=>$operation]+$extra);};
 $html=cupboardRequest(['view'=>'supplies','section'=>'shopping']);cupboardCheck(str_contains($html,'Labels &lt;fixture&gt;')&&str_contains($html,'No rolls left')&&str_contains($html,'Open product'),'Low/out supplies show exact specifications and links in shopping list');
 $change('claim',['owner'=>'Jay']);$claim=$item();cupboardCheck($claim['owner']==='Jay','Jay can claim the shared request');
 cupboardCheck(str_contains($change('claim',['owner'=>'Tony']),'already handling'),'Another partner cannot silently take an existing claim');
 cupboardCheck(str_contains($change('level',['stock_level'=>'Enough'],1),'changed'),'Stale stock updates cannot overwrite another partner');
 $change('release');$change('claim',['owner'=>'Tony']);$change('level',['stock_level'=>'Running low']);
 $buy=['action'=>'business_supply_save','return'=>'supplies','return_section'=>'purchases','request_key'=>str_repeat('d',32),'cupboard_id'=>$id,'cupboard_revision'=>$item()['revision'],'item'=>'Labels purchase','category'=>'Labels','quantity'=>3,'supplier'=>'Preferred shop','ordered_date'=>'2025-02-01','expected_date'=>'2027-01-01','status'=>'Ordered','item_cost'=>'15.00','shipping'=>'2.00','payment_status'=>'Paid','paid_date'=>'2025-02-01','product_url'=>'https://example.com/labels'];
 cupboardRequest(['view'=>'supplies','section'=>'purchases'],$buy);$pid=(int)$db->query('SELECT MAX(id) FROM business_supplies')->fetchColumn();$purchase=static function()use($db,$pid):array{return $db->query('SELECT * FROM business_supplies WHERE id='.$pid)->fetch(PDO::FETCH_ASSOC);};
 cupboardCheck((int)$purchase()['cupboard_id']===$id&&$item()['stock_level']==='Running low','Purchase links to cupboard but does not claim stock has arrived');
 cupboardRequest(['view'=>'supplies','section'=>'purchases'],$buy);cupboardCheck((int)$db->query('SELECT COUNT(*) FROM business_supplies')->fetchColumn()===2,'Retrying a linked purchase does not create duplicate spending');
 $buy['request_key']=str_repeat('e',32);$buy['cupboard_revision']=$item()['revision'];cupboardCheck(str_contains(cupboardRequest(['view'=>'supplies','section'=>'purchases'],$buy),'already on the way'),'Second open order for the same supply is blocked');
 $html=cupboardRequest(['view'=>'supplies','section'=>'shopping']);cupboardCheck(str_contains($html,'Already on the way')&&str_contains($html,'Tony is handling this'),'Shopping list shows ownership and incoming purchase');
 $receive=static function(int $qty,string $level,?int $pr=null,?int $cr=null)use($purchase,$item,$pid):string{return cupboardRequest(['view'=>'supplies','section'=>'purchases'],['action'=>'supply_delivery_receive','return'=>'supplies','return_section'=>'purchases','purchase_id'=>$pid,'purchase_revision'=>$pr??$purchase()['revision'],'cupboard_revision'=>$cr??$item()['revision'],'received_quantity'=>$qty,'stock_level'=>$level,'stock_note'=>'Delivery checked']);};
 $oldRevision=(int)$item()['revision'];$change('level',['stock_level'=>'Out']);$receive(1,'Running low',null,$oldRevision);cupboardCheck((int)$purchase()['received_quantity']===0,'A stale cupboard update rolls back the whole delivery receipt');
 $receive(1,'Running low');cupboardCheck($purchase()['status']==='Dispatched'&&(int)$purchase()['received_quantity']===1&&$item()['owner']==='Tony','Part delivery preserves outstanding quantity and claim');
 cupboardCheck(str_contains($receive(3,'Enough'),'quantity received'),'Over-receipts are rejected');
 $finalHtml=$receive(2,'Enough');cupboardCheck($purchase()['status']==='Received'&&(int)$purchase()['received_quantity']===3&&$item()['stock_level']==='Enough'&&$item()['owner']==='','Final check-in clears claim and explicitly replenishes the cupboard: '.json_encode([$purchase(),$item()]).' '.(preg_match('/class="error"[^>]*>(.*?)<\/p>/s',$finalHtml,$m)?$m[1]:''));
 $html=cupboardRequest(['view'=>'supplies','section'=>'shopping']);cupboardCheck(!str_contains($html,'id="cupboard-'.$id.'"'),'Restocked unclaimed supplies leave the shopping list');
 $history=cupboardRequest(['view'=>'supplies','section'=>'purchases','cupboard_filter'=>$id]);cupboardCheck(str_contains($history,'Labels purchase')&&!str_contains($history,'Legacy envelopes'),'Per-item history includes received orders and excludes other supplies');
 $change('archive');cupboardCheck(!(int)$item()['active'],'Archiving preserves the supply record');$change('restore');cupboardCheck((int)$item()['active']===1,'Archived supplies can be restored');
 $bad=array_replace($input,['id'=>$id,'revision'=>$item()['revision'],'backup_url'=>'javascript:alert(1)']);$saved=$item();cupboardRequest(['view'=>'supplies'],$bad);cupboardCheck($saved===$item(),'Unsafe supplier links cannot be saved');
 $from=array_replace($input,['request_key'=>str_repeat('f',32),'name'=>'Saved legacy envelopes','source_purchase_id'=>1,'source_revision'=>1]);cupboardRequest(['view'=>'supplies'],$from);cupboardCheck((int)$db->query('SELECT cupboard_id FROM business_supplies WHERE id=1')->fetchColumn()>0,'An existing purchase can seed and link a cupboard entry');
 $report=cupboardRequest(['view'=>'reports','type'=>'outgoings','range'=>'all']);cupboardCheck(str_contains($report,'£17.00'),'Reports include actual purchase spending once');
 cupboardCheck($before===$db->query('SELECT * FROM products ORDER BY id')->fetchAll(PDO::FETCH_ASSOC),'Cupboard and deliveries must not alter sale-stock inventory');
 echo "PASS: legacy migration, shared catalogue, low-stock list, claim/stale protection, linked purchases, duplicate protection, partial/final receipts, rollback, archive/restore, safe links, history and spending isolation.\n";
}finally{$db=null;foreach(glob($temp.'/*')?:[] as $file)unlink($file);rmdir($temp);}
